insert into public.exercises
  (id, owner_id, slug, name, kind, primary_muscles, secondary_muscles, equipment, difficulty, uses_weight, starting_position, steps, breathing, mistakes, safety, animation)
values
  ('8c323f0e-6bce-4bf5-a10a-d88c2c91cdeb', null, 'hip-thrust-machine', 'Hip Thrust Machine', 'reps', array['Glutes']::text[], array['Hamstrings', 'Core']::text[], array['Hip thrust machine']::text[], 'beginner', true, 'Sit with your upper back against the pad''s edge, the hip belt or pad across your hip crease, feet flat about hip-width apart and shins roughly vertical at the top.', array['Brace your core and tuck your chin slightly so your ribs stay down.', 'Drive through your heels and push your hips up until your body forms a straight line from shoulders to knees.', 'Squeeze your glutes for a one-second pause at the top.', 'Lower your hips under control until they are just above the seat, then repeat.']::text[], 'Exhale as you drive up, inhale as you lower.', array['Arching the lower back at the top instead of finishing with the glutes.', 'Pushing through the toes so the quads take over.', 'Bouncing out of the bottom position.']::text[], array['Stop at a straight line — you do not need to over-extend.', 'Adjust the pad so it never presses on your stomach or ribs.']::text[], 'hip-thrust-machine'),
  ('ac8d797e-31e4-4f4d-b51c-8c644ea9bcbb', null, 'db-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'reps', array['Hamstrings', 'Glutes']::text[], array['Lower back', 'Forearms']::text[], array['Dumbbells']::text[], 'beginner', true, 'Stand tall, feet hip-width, a dumbbell in each hand resting in front of your thighs, knees softly bent.', array['Keep a soft bend in the knees and push your hips straight back.', 'Let the dumbbells slide down close to your legs while your back stays flat.', 'Stop when you feel a strong hamstring stretch — usually around mid-shin.', 'Drive your hips forward to return to standing, squeezing your glutes at the top.']::text[], 'Inhale and brace before you hinge, exhale as you stand back up.', array['Rounding the back to reach lower.', 'Turning it into a squat by bending the knees a lot.', 'Letting the dumbbells drift away from the legs.']::text[], array['Only go as low as you can with a flat back.', 'Start light — this exercise is about the hinge pattern, not heavy weight.']::text[], 'db-romanian-deadlift'),
  ('2b3436a6-89a9-44f7-9869-93388273e679', null, 'leg-press', 'Leg Press', 'reps', array['Quadriceps', 'Glutes']::text[], array['Hamstrings', 'Adductors']::text[], array['Leg press machine']::text[], 'beginner', true, 'Sit with your back and hips flat against the pad and feet hip-width in the middle of the platform.', array['Release the safety handles and hold the side grips.', 'Bend your knees to lower the platform until your knees are around 90 degrees.', 'Press through your whole foot to push the platform away.', 'Stop just short of locking your knees, then repeat.']::text[], 'Inhale on the way down, exhale as you press.', array['Letting the hips curl off the seat at the bottom.', 'Locking the knees hard at the top.', 'Knees caving inward.']::text[], array['Always re-engage the safety handles before getting out.', 'Keep your lower back in contact with the pad.']::text[], 'leg-press'),
  ('68755bc3-b6af-4bbe-a66a-6a1582b95ff0', null, 'hip-abduction-machine', 'Hip Abduction Machine', 'reps', array['Glutes (side)']::text[], array['Hip stabilisers']::text[], array['Hip abduction machine']::text[], 'beginner', true, 'Sit upright with your back on the pad and the outside of your knees against the leg pads, knees together.', array['Brace your core and hold the handles lightly.', 'Push your knees outward against the pads as far as is comfortable.', 'Pause briefly at the widest point.', 'Let your knees come back together slowly without letting the weights touch.']::text[], 'Exhale as you push out, inhale as you return.', array['Using momentum and letting the stack slam.', 'Rocking the torso to move the weight.']::text[], array['Use a range of motion that feels comfortable for your hips.']::text[], 'hip-abduction-machine'),
  ('767bc262-aebb-4ddf-a652-755cacb885e9', null, 'seated-leg-curl', 'Seated Leg Curl', 'reps', array['Hamstrings']::text[], array['Calves (minor)']::text[], array['Seated leg curl machine']::text[], 'beginner', true, 'Sit with knees lined up with the machine''s pivot, the lower pad just above your heels and the thigh pad snug.', array['Hold the handles and keep your back against the seat.', 'Curl your heels down and back under the seat as far as you can.', 'Pause and squeeze your hamstrings.', 'Return slowly until your legs are almost straight.']::text[], 'Exhale as you curl, inhale as you return.', array['Lifting the hips off the seat.', 'Letting the weight snap back up.']::text[], array['Align your knee with the pivot point before starting.']::text[], 'seated-leg-curl'),
  ('b08aecd3-0cac-406a-b855-44d9c972e838', null, 'chest-press-machine', 'Chest Press Machine', 'reps', array['Chest']::text[], array['Front shoulders', 'Triceps']::text[], array['Chest press machine']::text[], 'beginner', true, 'Adjust the seat so the handles are at mid-chest height. Sit tall with your back on the pad and shoulder blades gently pulled back.', array['Grip the handles with your wrists straight.', 'Press the handles forward until your arms are almost straight.', 'Pause briefly without locking the elbows.', 'Return slowly until you feel a light stretch across the chest.']::text[], 'Exhale as you press, inhale as you return.', array['Shrugging the shoulders up toward the ears.', 'Flaring the elbows straight out to the sides.']::text[], array['Keep your back on the pad throughout.']::text[], 'chest-press-machine'),
  ('2489ebd3-2722-4244-8b95-ab654e65fe1e', null, 'lat-pulldown', 'Lat Pulldown', 'reps', array['Upper back (lats)']::text[], array['Biceps', 'Rear shoulders']::text[], array['Cable pulldown machine']::text[], 'beginner', true, 'Sit with thighs under the pads, grip the bar a little wider than shoulder-width, arms straight overhead.', array['Lean back very slightly and lift your chest.', 'Pull the bar down toward your upper chest, driving your elbows down and back.', 'Pause when the bar is near your collarbone.', 'Let the bar rise slowly until your arms are straight again.']::text[], 'Exhale as you pull down, inhale as the bar rises.', array['Pulling the bar behind the neck.', 'Swinging the torso back to move the weight.']::text[], array['Keep the movement smooth and controlled on the way up.']::text[], 'lat-pulldown'),
  ('8d191ee5-7884-4fba-97e6-f67bf3698290', null, 'seated-cable-row', 'Seated Cable Row', 'reps', array['Mid back', 'Lats']::text[], array['Biceps', 'Rear shoulders']::text[], array['Cable row machine']::text[], 'beginner', true, 'Sit with feet on the platform, knees softly bent, holding the handle with arms extended and back tall.', array['Keep your chest up and your torso still.', 'Pull the handle to your lower ribs, squeezing your shoulder blades together.', 'Pause for a moment.', 'Extend your arms slowly back to the start.']::text[], 'Exhale as you pull, inhale as you extend.', array['Rocking back and forth to move the weight.', 'Rounding the back at the front of the movement.']::text[], array['Keep a slight bend in the knees to protect the lower back.']::text[], 'seated-cable-row'),
  ('67a64a79-d39f-4c0a-9468-e32f94a07090', null, 'db-lateral-raise', 'Dumbbell Lateral Raise', 'reps', array['Side shoulders']::text[], array['Upper traps']::text[], array['Dumbbells']::text[], 'beginner', true, 'Stand tall holding light dumbbells at your sides, palms facing in, elbows slightly bent.', array['Raise your arms out to the sides, leading with your elbows.', 'Stop at shoulder height so your arms form a ''T''.', 'Pause briefly.', 'Lower slowly back to your sides.']::text[], 'Exhale as you raise, inhale as you lower.', array['Using weights that are too heavy and swinging.', 'Shrugging the shoulders up.']::text[], array['Light weights are normal for this exercise — control matters more than load.']::text[], 'db-lateral-raise'),
  ('d27ddbe2-57cd-4119-92a3-d298fdc20ab7', null, 'db-biceps-curl', 'Dumbbell Biceps Curl', 'reps', array['Biceps']::text[], array['Forearms']::text[], array['Dumbbells']::text[], 'beginner', true, 'Stand tall with a dumbbell in each hand, arms by your sides, palms facing forward.', array['Keep your upper arms still against your sides.', 'Bend your elbows to curl the dumbbells up toward your shoulders.', 'Squeeze at the top.', 'Lower slowly until your arms are straight.']::text[], 'Exhale as you curl, inhale as you lower.', array['Swinging the body.', 'Letting the elbows drift forward.']::text[], array['Keep your wrists neutral and your core braced.']::text[], 'db-biceps-curl'),
  ('23a36ab2-3c2e-49a7-9fcc-9e78de2ec855', null, 'triceps-rope-pushdown', 'Triceps Rope Pushdown', 'reps', array['Triceps']::text[], array['Forearms']::text[], array['Cable machine', 'Rope attachment']::text[], 'beginner', true, 'Stand facing a high cable with a rope attachment, elbows bent and tucked at your sides, hands at chest height.', array['Keep your elbows pinned to your sides.', 'Push the rope down until your arms are straight, spreading the rope ends slightly apart.', 'Pause and squeeze the triceps.', 'Let your forearms rise back to the start under control.']::text[], 'Exhale as you push down, inhale as you return.', array['Letting the elbows move forward and back.', 'Leaning over the rope to use body weight.']::text[], array['Stand close enough that the cable doesn''t pull you off balance.']::text[], 'triceps-rope-pushdown'),
  ('ebd91cb4-e6e1-4703-8991-f51e76c4cedd', null, 'treadmill-walk', 'Treadmill Walking', 'cardio', array['Cardiovascular system']::text[], array['Legs', 'Glutes']::text[], array['Treadmill']::text[], 'beginner', false, 'Stand on the side rails, clip the safety key to your clothing and start the belt at a slow speed before stepping on.', array['Walk for 2–3 minutes at an easy pace to warm up.', 'Increase to a comfortable or moderately brisk pace — you should still be able to talk.', 'Swing your arms naturally and look ahead, not down.', 'Finish with 2–3 minutes of slower walking.']::text[], 'Breathe naturally; aim for a pace where you can speak in sentences.', array['Holding the handrails the whole time.', 'Starting too fast and fading early.']::text[], array['Always use the safety key.', 'Slow down gradually before stepping off.']::text[], 'treadmill-walk'),
  ('2ddc45c4-2922-415d-a835-1282bd48d373', null, 'mobility-flow', 'Hip, Shoulder & Upper-Back Mobility', 'mobility', array['Hips', 'Thoracic spine', 'Shoulders']::text[], array['Core']::text[], array['Mat']::text[], 'beginner', false, 'Start on hands and knees on a mat: hands under shoulders, knees under hips.', array['Cat–cow: round your back up, then let your chest sink and look forward. 8 slow reps.', 'Thread the needle: slide one arm under your body and rotate, then open it to the ceiling. 5 per side.', 'Hip rocks: sit your hips back toward your heels and return. 8 reps.', 'Finish with slow arm circles while standing, 10 forward and 10 back.']::text[], 'Move with your breath — slow inhales and long exhales.', array['Rushing through the movements.', 'Forcing positions that pinch or hurt.']::text[], array['Mobility should feel like gentle stretching, never sharp pain.']::text[], 'mobility-flow'),
  ('a5653569-91cc-4ffa-ba3d-540f3b52a230', null, 'glute-bridge', 'Glute Bridge', 'reps', array['Glutes']::text[], array['Hamstrings', 'Core']::text[], array['Mat']::text[], 'beginner', false, 'Lie on your back with knees bent, feet flat and hip-width apart, arms by your sides.', array['Brace your core and press your lower back gently into the floor.', 'Push through your heels to lift your hips until your body is straight from shoulders to knees.', 'Squeeze your glutes for one to two seconds.', 'Lower slowly back to the floor.']::text[], 'Exhale as you lift, inhale as you lower.', array['Arching the lower back instead of using the glutes.', 'Feet too far from the hips.']::text[], array['Keep your neck relaxed on the floor — don''t press your head down.']::text[], 'glute-bridge'),
  ('15070867-0f87-4cca-b560-49cd933754d8', null, 'low-step-up', 'Low Step-Ups', 'reps', array['Glutes', 'Quadriceps']::text[], array['Hamstrings', 'Balance']::text[], array['Low box or step']::text[], 'beginner', true, 'Stand facing a stable, low step (about shin height) and place one whole foot on it.', array['Lean your torso slightly forward over the front foot.', 'Drive through the front heel to step up until that leg is straight.', 'Bring the back foot up lightly, or keep it hovering for balance.', 'Step back down slowly with the same back foot. Finish all reps, then switch legs.']::text[], 'Exhale as you step up, inhale as you step down.', array['Pushing off the back foot instead of the front leg.', 'Letting the front knee cave inward.']::text[], array['Use a stable step and hold a rail or wall if needed.', 'Add dumbbells only once balance feels solid.']::text[], 'low-step-up'),
  ('6146b71d-ec43-439a-930c-476f177e07dc', null, 'cable-glute-kickback', 'Cable Glute Kickback', 'reps', array['Glutes']::text[], array['Hamstrings', 'Core']::text[], array['Cable machine', 'Ankle strap']::text[], 'beginner', true, 'Attach an ankle strap to a low cable. Face the machine, hold the frame and hinge forward slightly.', array['Brace your core and keep your hips square.', 'Kick the working leg back and slightly up, squeezing the glute.', 'Pause without arching your lower back.', 'Return slowly. Finish all reps, then switch legs.']::text[], 'Exhale as you kick back, inhale as you return.', array['Swinging the leg with momentum.', 'Arching the back to lift the leg higher.']::text[], array['Hold the machine for balance; keep the movement small and controlled.']::text[], 'cable-glute-kickback'),
  ('5c407f94-ee10-4011-8cac-cb1ec72e3e53', null, 'incline-chest-press-machine', 'Incline Chest Press Machine', 'reps', array['Upper chest']::text[], array['Front shoulders', 'Triceps']::text[], array['Incline chest press machine']::text[], 'beginner', true, 'Set the seat so the handles line up with your upper chest. Sit back against the inclined pad.', array['Grip the handles with straight wrists and shoulder blades gently back.', 'Press up and forward until your arms are almost straight.', 'Pause briefly.', 'Return slowly to the starting position.']::text[], 'Exhale as you press, inhale as you return.', array['Arching the lower back off the pad.', 'Locking out the elbows hard.']::text[], array['Keep the movement controlled, especially on the way back.']::text[], 'incline-chest-press-machine'),
  ('64a7cac3-70c3-49be-9a25-6bcdfab15118', null, 'chest-supported-row', 'Chest-Supported Row', 'reps', array['Mid back', 'Lats']::text[], array['Rear shoulders', 'Biceps']::text[], array['Chest-supported row machine or incline bench + dumbbells']::text[], 'beginner', true, 'Lie chest-down on the pad, arms hanging straight and holding the handles or dumbbells.', array['Keep your chest on the pad.', 'Row your elbows back toward your hips, squeezing your shoulder blades.', 'Pause at the top.', 'Lower slowly until your arms are straight.']::text[], 'Exhale as you row, inhale as you lower.', array['Lifting the chest off the pad.', 'Shrugging instead of rowing.']::text[], array['The pad supports your back — let it do its job and keep the movement strict.']::text[], 'chest-supported-row'),
  ('f042b3cc-1da0-4867-a918-97924066b815', null, 'db-hammer-curl', 'Dumbbell Hammer Curl', 'reps', array['Biceps', 'Brachialis']::text[], array['Forearms']::text[], array['Dumbbells']::text[], 'beginner', true, 'Stand tall, a dumbbell in each hand at your sides, palms facing your body.', array['Keep your palms facing in the whole time.', 'Curl the dumbbells toward your shoulders without moving your upper arms.', 'Pause at the top.', 'Lower slowly to full extension.']::text[], 'Exhale as you curl, inhale as you lower.', array['Swinging the dumbbells.', 'Rotating the palms up.']::text[], array['Keep a neutral wrist and a braced core.']::text[], 'db-hammer-curl'),
  ('154d5036-8f68-42b5-9ce1-7d602ae6539f', null, 'cable-rope-hammer-curl', 'Cable Rope Hammer Curl', 'reps', array['Biceps', 'Brachialis']::text[], array['Forearms']::text[], array['Cable machine', 'Rope attachment']::text[], 'beginner', true, 'Attach a rope to the low pulley and stand facing the machine, a small step back. Hold one end of the rope in each hand, palms facing each other, arms straight down in front of your thighs.', array['Tuck your elbows in at your sides and keep your upper arms still.', 'Curl the rope up toward your chest, keeping your palms facing each other the whole time.', 'Squeeze at the top, with the rope ends just in front of your shoulders.', 'Lower slowly until your arms are straight again.']::text[], 'Exhale as you curl, inhale as you lower.', array['Leaning back to swing the weight up.', 'Letting the elbows drift forward or out to the sides.', 'Letting the weight stack crash down between reps.']::text[], array['Start light — the cable feels heavier than the same number on a dumbbell.', 'Stand close enough that the cable doesn''t pull you forward off balance.']::text[], 'cable-rope-hammer-curl'),
  ('972a634d-f8fa-4ffc-aed1-d6ffc82527fe', null, 'forearm-plank', 'Forearm Plank', 'time', array['Core']::text[], array['Shoulders', 'Glutes']::text[], array['Mat']::text[], 'beginner', false, 'Forearms on the floor, elbows under shoulders, legs straight behind you on your toes.', array['Lift your hips so your body forms a straight line from head to heels.', 'Squeeze your glutes and gently brace your stomach.', 'Hold the position without letting your hips sag or pike up.', 'Lower your knees to the floor to finish.']::text[], 'Keep breathing slowly — don''t hold your breath.', array['Hips sagging toward the floor.', 'Hips piked high in the air.']::text[], array['Drop to your knees if your lower back starts to ache.']::text[], 'forearm-plank'),
  ('39403fb1-5741-4f4e-831f-c577362c4b74', null, 'crunch', 'Crunch', 'reps', array['Abs']::text[], array['Obliques']::text[], array['Exercise mat']::text[], 'beginner', false, 'Lie on your back on a mat, knees bent and feet flat on the floor, hip-width apart. Rest your arms by your sides or reach them toward your knees.', array['Tighten your stomach and press your lower back gently into the floor.', 'Curl your head and shoulders up off the floor, reaching your hands toward your knees.', 'Stop when your shoulder blades are off the floor — your lower back stays down.', 'Lower back down slowly, one bit of your spine at a time.']::text[], 'Exhale as you curl up, inhale as you lower.', array['Yanking your head up by the neck.', 'Coming all the way up so the hips do the work.', 'Dropping back down quickly instead of lowering with control.']::text[], array['Keep a fist-sized space between your chin and chest so your neck stays relaxed.', 'Stop if you feel it in your lower back rather than your stomach.']::text[], 'crunch'),
  ('beecd4e7-f6b1-43a4-a196-21590f6693ce', null, 'decline-sit-up', 'Decline Bench Sit-Up', 'reps', array['Abs']::text[], array['Obliques', 'Hip flexors']::text[], array['Decline (ab) bench']::text[], 'intermediate', false, 'Sit on the decline bench and hook your feet under the foot pads, knees bent over the top. Lie back so your back rests on the pad, arms crossed on your chest.', array['Tighten your stomach and curl your head and shoulders up first.', 'Keep curling until you are sitting up, chest toward your knees.', 'Pause briefly at the top.', 'Lower back down slowly until your back is just above or touching the pad.']::text[], 'Exhale as you sit up, inhale as you lower.', array['Throwing the arms forward to swing up.', 'Pulling on the head or neck.', 'Dropping back onto the bench.']::text[], array['Start with the bench on its lowest angle and make it steeper as you get stronger.', 'Make sure your feet are firmly hooked before you lie back.']::text[], 'decline-sit-up'),
  ('8f79dde3-1e39-470e-b368-200de6805550', null, 'russian-twist', 'Russian Twist', 'reps', array['Obliques', 'Abs']::text[], array['Hip flexors']::text[], array['Exercise mat', 'Light dumbbell or plate (optional)']::text[], 'beginner', true, 'Sit on a mat with your knees bent and heels on the floor. Lean back until you feel your stomach working, back straight, holding your hands or a light weight in front of your chest.', array['Keep your chest up and your back straight.', 'Turn your shoulders to one side and bring your hands down beside that hip.', 'Come back through the middle and turn to the other side.', 'Each turn to one side counts as one rep — count both sides.']::text[], 'Exhale as you turn to the side, inhale as you come back to the middle.', array['Only moving the arms instead of turning the shoulders.', 'Rounding the back.', 'Going so fast that it becomes a swing.']::text[], array['Keep your heels on the floor until the movement feels easy; lift them only to make it harder.', 'Start without a weight.']::text[], 'russian-twist'),
  ('5804fbad-c542-4a32-b14a-bff3022cce18', null, 'dead-bug', 'Dead Bug', 'reps', array['Core']::text[], array['Hip flexors']::text[], array['Mat']::text[], 'beginner', false, 'Lie on your back, arms pointing at the ceiling, hips and knees bent to 90 degrees.', array['Press your lower back gently into the floor.', 'Slowly extend one arm overhead and the opposite leg out straight.', 'Stop just before your lower back lifts off the floor.', 'Return to the start and repeat on the other side.']::text[], 'Exhale as you extend, inhale as you return.', array['Arching the lower back as the leg lowers.', 'Moving too fast.']::text[], array['Shorten the range if you can''t keep your back flat.']::text[], 'dead-bug'),
  ('44bc8a82-6db6-4db5-a9db-5500f8b78163', null, 'goblet-squat', 'Goblet Squat', 'reps', array['Quadriceps', 'Glutes']::text[], array['Core', 'Adductors']::text[], array['Dumbbell or kettlebell']::text[], 'beginner', true, 'Stand with feet slightly wider than hips, holding a dumbbell vertically against your chest.', array['Brace your core and keep your chest up.', 'Sit down between your heels, knees tracking over your toes.', 'Go as low as you can with a flat back.', 'Drive through your whole foot to stand up.']::text[], 'Inhale on the way down, exhale as you stand.', array['Heels lifting off the floor.', 'Knees collapsing inward.']::text[], array['Squat to a box first if depth feels unstable.']::text[], 'goblet-squat'),
  ('b245c9fd-302c-4330-bb0b-c9ef06b105ca', null, 'incline-push-up', 'Incline Push-Up', 'reps', array['Chest']::text[], array['Triceps', 'Front shoulders', 'Core']::text[], array['Bench or sturdy surface']::text[], 'beginner', false, 'Hands on a bench slightly wider than shoulders, body straight from head to heels.', array['Brace your core and squeeze your glutes.', 'Bend your elbows to lower your chest toward the bench.', 'Keep elbows at roughly 45 degrees from your body.', 'Press back up to straight arms.']::text[], 'Inhale on the way down, exhale as you press.', array['Hips sagging.', 'Elbows flaring straight out.']::text[], array['Use a higher surface to make it easier.']::text[], 'incline-push-up'),
  ('8b9e62d3-98ee-419e-b533-65d96cad2a44', null, 'db-shoulder-press', 'Seated Dumbbell Shoulder Press', 'reps', array['Shoulders']::text[], array['Triceps', 'Upper chest']::text[], array['Dumbbells', 'Bench with back support']::text[], 'beginner', true, 'Sit upright with back support, dumbbells at shoulder height, palms facing forward.', array['Brace your core and keep your back against the pad.', 'Press the dumbbells overhead until your arms are almost straight.', 'Pause briefly.', 'Lower slowly to shoulder height.']::text[], 'Exhale as you press, inhale as you lower.', array['Arching the lower back.', 'Bringing the dumbbells down too fast.']::text[], array['Choose a weight you can control overhead.']::text[], 'db-shoulder-press'),
  ('f1ce85f4-9f7a-489d-b568-a49e07e8ab0f', null, 'stationary-bike', 'Stationary Bike', 'cardio', array['Cardiovascular system']::text[], array['Quadriceps', 'Glutes']::text[], array['Exercise bike']::text[], 'beginner', false, 'Set the seat so your knee is slightly bent at the bottom of each pedal stroke.', array['Warm up for 3 minutes at low resistance.', 'Ride at a steady, comfortable effort.', 'Keep your shoulders relaxed and back tall.', 'Cool down for 2–3 minutes at an easy pace.']::text[], 'Breathe steadily; you should be able to talk.', array['Seat too low, causing knee strain.', 'Resistance so high that you rock side to side.']::text[], array['Adjust the seat before you start.']::text[], 'stationary-bike'),
  ('f63fdbf8-d1be-41cd-a482-4c76dc08b73b', null, 'leg-extension', 'Leg Extension', 'reps', array['Quadriceps']::text[], array[]::text[], array['Leg extension machine']::text[], 'beginner', true, 'Sit with your back against the pad, knees lined up with the machine''s pivot point and the shin pad resting just above your ankles. Hold the side handles.', array['Brace your core and keep your back and hips against the seat.', 'Straighten your knees to lift the pad until your legs are almost straight.', 'Squeeze the front of your thighs for a moment at the top.', 'Lower slowly until your knees are back at about 90 degrees, then repeat.']::text[], 'Exhale as you lift, inhale as you lower.', array['Swinging the weight up with momentum.', 'Lifting the hips off the seat to help.', 'Letting the weight drop quickly on the way down.']::text[], array['Line your knees up with the machine''s pivot so the joint isn''t strained.', 'Stay in a pain-free range — stop a little short of the top if your knees complain.']::text[], 'leg-extension'),
  ('2e9f3e11-46d7-4efa-8eb2-26bbbd3373fc', null, 'lying-leg-curl', 'Lying Leg Curl', 'reps', array['Hamstrings']::text[], array['Calves']::text[], array['Lying leg curl machine']::text[], 'beginner', true, 'Lie face down on the bench with your knees just past the end of the pad and the roller resting on the back of your lower legs, just above the heels. Hold the handles.', array['Press your hips gently into the pad and keep them there.', 'Bend your knees to curl the roller up towards your glutes.', 'Pause and squeeze the back of your thighs.', 'Lower slowly until your legs are almost straight, then repeat.']::text[], 'Exhale as you curl, inhale as you lower.', array['Lifting the hips off the bench to finish the rep.', 'Kicking the weight up fast.', 'Letting the weight drop on the way down.']::text[], array['Keep your hips down so your lower back doesn''t arch.', 'Start light — the hamstrings cramp easily at first.']::text[], 'lying-leg-curl'),
  ('c4659309-0dc5-4ca4-a4f1-04efef754942', null, 'preacher-curl', 'Preacher Curl', 'reps', array['Biceps']::text[], array['Brachialis', 'Forearms']::text[], array['Preacher bench', 'EZ bar or dumbbells']::text[], 'beginner', true, 'Sit at the preacher bench with your armpits snug against the top of the angled pad and the backs of your upper arms resting on it. Hold the EZ bar with an underhand grip, arms almost straight.', array['Keep your upper arms flat on the pad the whole time.', 'Curl the bar up towards your shoulders.', 'Squeeze your biceps at the top without letting your elbows lift.', 'Lower slowly until your arms are almost straight, then repeat.']::text[], 'Exhale as you curl, inhale as you lower.', array['Lifting the elbows off the pad.', 'Dropping into a fully locked-out arm at the bottom.', 'Leaning back to help the weight up.']::text[], array['Don''t bounce at the bottom — the stretched position is where the elbows are most at risk.', 'Use a lighter weight than for a standing curl.']::text[], 'preacher-curl'),
  ('5757cbde-2253-4d33-b3eb-b548cb39e4d5', null, 'chin-up', 'Chin-Up', 'reps', array['Lats', 'Biceps']::text[], array['Mid back', 'Rear shoulders', 'Forearms', 'Core']::text[], array['Pull-up bar', 'Assisted pull-up machine or band (optional)']::text[], 'intermediate', false, 'Hang from a pull-up bar with your hands about shoulder-width apart and palms facing you, arms straight and legs slightly bent or crossed behind you.', array['Pull your shoulders down and back to start the movement.', 'Pull yourself up by driving your elbows down towards your ribs.', 'Keep going until your chin is above the bar.', 'Lower yourself slowly all the way down to a full hang, then repeat.']::text[], 'Exhale as you pull up, inhale as you lower.', array['Swinging or kicking the legs to get up.', 'Only doing the top half of the movement.', 'Dropping down fast instead of lowering slowly.']::text[], array['If you can''t do one yet, use an assisted pull-up machine or a band, or practise lowering slowly from the top.', 'Don''t jerk at the bottom — keep a little tension in your shoulders.']::text[], 'chin-up'),
  ('522f0da1-ac1f-4e64-8482-d05b2f0a25ce', null, 'db-wrist-curl', 'Dumbbell Wrist Curl', 'reps', array['Forearms']::text[], array[]::text[], array['Dumbbells', 'Bench']::text[], 'beginner', true, 'Sit on the end of a bench with your forearms resting on your thighs, palms facing up, and your wrists just past your knees holding light dumbbells.', array['Let the dumbbells lower towards the floor, bending only at the wrist.', 'Curl your wrists up as high as you can while your forearms stay on your thighs.', 'Squeeze for a moment at the top.', 'Lower slowly back down, then repeat.']::text[], 'Breathe steadily — exhale as you curl up.', array['Lifting the forearms off the thighs.', 'Using too much weight and jerking it.', 'Rushing through tiny half reps.']::text[], array['Start very light — wrist tendons need time to get used to the work.', 'Stop if you feel sharp pain in the wrist.']::text[], 'db-wrist-curl'),
  ('5c9e6ba8-56b1-4df1-9b7c-8bc21e7116fb', null, 'db-reverse-wrist-curl', 'Reverse Wrist Curl', 'reps', array['Forearms']::text[], array[]::text[], array['Dumbbells', 'Bench']::text[], 'beginner', true, 'Sit on the end of a bench with your forearms on your thighs, palms facing down, and your hands just past your knees holding light dumbbells.', array['Let your hands drop down slowly, bending only at the wrist.', 'Lift the backs of your hands up as high as they go.', 'Pause for a moment at the top.', 'Lower with control, then repeat.']::text[], 'Breathe steadily — exhale as you lift.', array['Lifting the forearms off the thighs.', 'Going too heavy — these muscles are small.', 'Bouncing the weight at the bottom.']::text[], array['Use lighter dumbbells than for the palms-up version.', 'Stop if you feel sharp pain in the wrist or elbow.']::text[], 'db-reverse-wrist-curl'),
  ('ca561b9e-8c4c-49ef-bbb6-94647ca0ad85', null, 'farmers-carry', 'Farmer''s Carry', 'time', array['Forearms', 'Upper traps']::text[], array['Core', 'Glutes', 'Shoulders']::text[], array['Heavy dumbbells or kettlebells']::text[], 'beginner', true, 'Stand tall between two heavy dumbbells. Squat down with a flat back, grip them firmly and stand up with them at your sides.', array['Stand tall with your shoulders back and down and your core braced.', 'Walk forward with short, steady steps, keeping the weights still at your sides.', 'Keep your grip tight and don''t let your shoulders shrug up or lean to one side.', 'When the time is up, stop, squat down and set the weights down with a flat back.']::text[], 'Breathe steadily through your nose — don''t hold your breath.', array['Letting the shoulders round forward.', 'Leaning to one side.', 'Rushing with long, wobbly steps.']::text[], array['Pick up and put down the weights with a flat back, like a deadlift.', 'Make sure your walking path is clear.']::text[], 'farmers-carry'),
  ('81793a46-36bb-45b9-8649-46c026c1e1d3', null, 'db-walking-lunge', 'Dumbbell Walking Lunge', 'reps', array['Glutes', 'Quadriceps']::text[], array['Hamstrings', 'Adductors', 'Calves', 'Core']::text[], array['Dumbbells', 'Clear walking space']::text[], 'intermediate', true, 'Stand tall with a dumbbell in each hand at your sides, feet hip-width apart, with a clear path of at least ten big steps in front of you.', array['Take a long step forward with one leg and plant the whole foot.', 'Bend both knees and lower straight down until your back knee is just above the floor and your front thigh is about level with it.', 'Keep your chest up and your front knee in line with the middle of your foot.', 'Push through your front heel to stand up, bring the back foot forward and step straight into the next lunge with the other leg.']::text[], 'Inhale as you lower, exhale as you push back up.', array['Taking short steps, so the front knee travels far past the toes.', 'Leaning the upper body forward over the front leg.', 'Letting the front knee cave inward.', 'Dropping the back knee onto the floor.']::text[], array['Start with light dumbbells, or none, until your balance feels steady.', 'Make sure the floor in front of you is clear and not slippery.']::text[], 'db-walking-lunge')
